actions.script:
// 1. Fallback safe defaults
def rawPath = screenPath ?: "AgiWorkspace"
def componentName = "agi-ide" // Default fallback
def fileName = rawPath

// 2. Dynamically extract component name if passed as a composite path (e.g., "nursing-home/FacilityDetails")
if (rawPath.contains("/")) {
    def pathParts = rawPath.split("/")
    componentName = pathParts[0]
    fileName = pathParts[1]
} else if (context.componentName) {
    // Allow an explicit separate variable override parameter if passed by the fetch headers
    componentName = context.componentName
}

// 3. Build standard Moqui convention path matrix definitions programmatically
def fileLocation = "component://${componentName}/screen/${componentName}/${fileName}.xml"

try {
    def resourceReference = ec.resource.getLocationReference(fileLocation)

    // FALLBACK ATTEMPT: Scan the generic root screen folder if the nested component folder structural match fails
    if (!resourceReference || !resourceReference.exists) {
        fileLocation = "component://${componentName}/screen/${fileName}.xml"
        resourceReference = ec.resource.getLocationReference(fileLocation)
    }

    // 4. Stream the pristine text payload down the REST channel
    if (resourceReference && resourceReference.exists) {
        def rawTextPayload = resourceReference.getText()
        ec.web.sendTextResponse(rawTextPayload, "text/xml", null)
        ec.logger.info("⚡ Dynamic source-streamer localized asset at: [${fileLocation}]")
    } else {
        ec.web.sendTextResponse("", "text/xml", null)
    }
} catch (Exception ex) {
    ec.logger.error("Failed to execute flexible dynamic XML resource extraction", ex)
    ec.web.sendTextResponse("", "text/xml", null)
}

def targetForm = screenPath ?: "SampleForm"
def componentName = "agi-ide"

if (targetForm.contains("/")) {
    def pathParts = targetForm.split("/")
    componentName = pathParts[0]
    targetForm = pathParts[1]
}

String fileLocation = "component://${componentName}/screen/${componentName}/${targetForm}.xml".toString()

try {
    def resourceRef = ec.resource.getLocationReference(fileLocation)
    if (!resourceRef || !resourceRef.exists) {
        fileLocation = "component://${componentName}/screen/${targetForm}.xml".toString()
        resourceRef = ec.resource.getLocationReference(fileLocation)
    }

    if (resourceRef && resourceRef.exists) {
        // 1. Initialize the base screen renderer context
        org.moqui.impl.screen.ScreenRenderImpl sri = new org.moqui.impl.screen.ScreenRenderImpl(ec.screen)

        // 2. Set standard configuration states
        sri.rootScreen(fileLocation)
        sri.renderMode("qmeta".toString())

        // FIXED: Pull the webapp name from the servlet context instead of the web facade property block
        String resolvedWebappName = ec.web.request.servletContext.getInitParameter("moqui-name")
        sri.webappName(resolvedWebappName ? resolvedWebappName.toString() : "agi-ide")

        // 3. Bind a dedicated text stream writer to catch the compiled metadata output
        java.io.StringWriter sw = new java.io.StringWriter()
        sri.internalWriter = sw

        // 4. Force isolated internal parsing structures without running an endless browser loop
        sri.rootScreenDef = ec.screen.getScreenDefinition(fileLocation)
        sri.screenUrlInfo = org.moqui.impl.screen.ScreenUrlInfo.getScreenUrlInfo(sri, sri.rootScreenDef, new ArrayList<String>(), null, 0)
        sri.screenUrlInstance = sri.screenUrlInfo.getInstance(sri, false)

        // Process the widget nodes straight into our local StringWriter string buffer
        sri.doActualRender()

        // 5. Send the compiled text map down the wire
        def jsonMetadataTree = sw.toString()
        ec.web.sendTextResponse(jsonMetadataTree, "application/json", null)
    } else {
        ec.web.sendTextResponse('{"error": "Target layout asset file not found on disk context."}', "application/json", null)
    }
} catch (Exception ex) {
    ec.logger.error("Failed to build dynamic component widget metadata tree via isolated rendering pass", ex)
    ec.web.sendTextResponse('{"error": "Exception occurred during direct screen compilation pass. See server console logs."}', "application/json", null)
}
